describe("值类型方法的形参判据不挑接收者写法", () => {
  it.each(CELLS)("%s 接收者", async (_shape, src, messages) => {
    expect(await diags(src)).toEqual(messages === "（收）" ? [] : messages.split(" || "));
  });
});
